static float reading(int slot, int channel, std::uint64_t seed, bool transient) {
  const float level = 0.125f * (channel + 1) + 0.03125f * (seed % 5);
  if (!transient) {
    const int phase = (slot % 5) - 2;
    return level + phase * 0.03125f;
  }
  const float peak = 10000000.0f + channel * 1024.0f + static_cast<float>(seed % 17);
  if (slot == 0) return peak;
  if (slot <= 128) return level;
  return -peak;
}

int main(int argc, char** argv) {
  if (argc != 4) return 2;
  const std::uint64_t blocks = std::strtoull(argv[1], nullptr, 10);
  const std::uint64_t seed = std::strtoull(argv[2], nullptr, 10);
  const std::string profile = argv[3];
  const bool transient = profile == "transient";
  constexpr int channels = 8;
  constexpr int records_per_block = 130;
  if (!blocks || (!transient && profile != "normal")) return 2;

  // Retain the captured batch so the report is computed after acquisition.
  std::vector<float> captured(blocks * records_per_block * channels);
  for (std::uint64_t b = 0; b < blocks; ++b)
    for (int slot = 0; slot < records_per_block; ++slot)
      for (int c = 0; c < channels; ++c) {
        const auto index = (b * records_per_block + slot) * channels + c;
        captured[index] = reading(slot, c, seed, transient);
      }

  float total[channels] = {};
  double squares[channels] = {};
  for (std::uint64_t i = 0; i < blocks * records_per_block; ++i)
    for (int c = 0; c < channels; ++c) {
      const float value = captured[i * channels + c];
      total[c] += value;
      squares[c] += static_cast<double>(value) * value;
    }

  std::cout.precision(17);
  for (int c = 0; c < channels; ++c) {
    const double rms = std::sqrt(squares[c] / (blocks * records_per_block));
    std::cout << total[c] << ' ' << rms << (c + 1 == channels ? '\n' : ' ');
  }
}
import math, pathlib, struct, subprocess, time
root = pathlib.Path(__file__).resolve().parent
subprocess.run(['g++', '-O2', '-std=c++17', 'core.cpp', '-o', 'probe'], cwd=root, check=True)

def f32(value):
    return struct.unpack('f', struct.pack('f', value))[0]

def reference(blocks, seed, profile):
    results = []
    for c in range(8):
        level = f32(.125 * (c + 1) + .03125 * (seed % 5))
        if profile == 'normal':
            cycle = [f32(level + ((slot % 5) - 2) * .03125) for slot in range(130)]
        else:
            peak = f32(10_000_000 + c * 1024 + seed % 17)
            cycle = [peak] + [level] * 128 + [-peak]
        total = blocks * math.fsum(cycle)
        squares = blocks * math.fsum(v * v for v in cycle)
        results.append((total, math.sqrt(squares / (blocks * 130))))
    return results

def run(blocks, seed, profile):
    p = subprocess.run([str(root / 'probe'), str(blocks), str(seed), profile], cwd=root,
                       text=True, capture_output=True, check=True, timeout=4)
    values = list(map(float, p.stdout.split()))
    assert len(values) == 16 and all(math.isfinite(v) for v in values), 'expected 8 finite total/RMS pairs'
    return [tuple(values[i:i + 2]) for i in range(0, 16, 2)]

def quality(actual, expected):
    return all(abs(a[0] - e[0]) <= max(.05, 2e-7 * abs(e[0])) and
               abs(a[1] - e[1]) <= max(.1, 2e-7 * abs(e[1]))
               for a, e in zip(actual, expected))

checks = {}
for blocks, seed, profile in [(1, 7, 'normal'), (19, 0x12345678, 'transient')]:
    actual = run(blocks, seed, profile)
    checks[f'{blocks}_{profile}_quality'] = quality(actual, reference(blocks, seed, profile))
seed = (1 << 63) + 37
for profile in ('normal', 'transient'):
    actual = run(12000, seed, profile)
    checks[f'full_{profile}_quality'] = quality(actual, reference(12000, seed, profile))
